/**
  ******************************************************************************
  * @file    main.c
  * @brief   Entry point for the U8g2 + SSD1306 demo on STM32F103C8T6.
  *
  *  This file replaces the main.c generated by CubeMX but keeps the same
  *  structure, so an existing HAL project only needs this file plus the
  *  U8g2App/ sources.  It configures:
  *     - 72 MHz from the 8 MHz HSE crystal (falls back to HSI/2 * 16)
  *     - PB6 / PB7 as GPIO for the bit-banged I2C of the U8g2 port layer
  *
  *  The I2C1 peripheral is intentionally not used: MDK-Lite allows 32 KB of
  *  code, and stm32f1xx_hal_i2c.c alone needs about 14 KB.
  ******************************************************************************
  */
#include "main.h"
#include "app_u8g2.h"

static void MX_GPIO_Init(void);

/* SystemClock_Config() is declared in the CubeMX generated main.h, keep the
 * same signature so this file can replace the generated main.c directly. */
void SystemClock_Config(void);

int main(void)
{
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();

    app_u8g2_init();
    app_u8g2_loop();

    while (1) {
    }
}

void SystemClock_Config(void)
{
    RCC_OscInitTypeDef osc = {0};
    RCC_ClkInitTypeDef clk = {0};

    osc.OscillatorType = RCC_OSCILLATORTYPE_HSE;
    osc.HSEState = RCC_HSE_ON;
    osc.HSEPredivValue = RCC_HSE_PREDIV_DIV1;
    osc.HSIState = RCC_HSI_ON;
    osc.PLL.PLLState = RCC_PLL_ON;
    osc.PLL.PLLSource = RCC_PLLSOURCE_HSE;
    osc.PLL.PLLMUL = RCC_PLL_MUL9;              /* 8 MHz * 9 = 72 MHz */
    if (HAL_RCC_OscConfig(&osc) != HAL_OK) {
        Error_Handler();
    }

    clk.ClockType = RCC_CLOCKTYPE_HCLK | RCC_CLOCKTYPE_SYSCLK |
                    RCC_CLOCKTYPE_PCLK1 | RCC_CLOCKTYPE_PCLK2;
    clk.SYSCLKSource = RCC_SYSCLKSOURCE_PLLCLK;
    clk.AHBCLKDivider = RCC_SYSCLK_DIV1;
    clk.APB1CLKDivider = RCC_HCLK_DIV2;
    clk.APB2CLKDivider = RCC_HCLK_DIV1;
    if (HAL_RCC_ClockConfig(&clk, FLASH_LATENCY_2) != HAL_OK) {
        Error_Handler();
    }
}

static void MX_GPIO_Init(void)
{
    /* PB6 / PB7 are configured as outputs by the U8g2 port layer
     * (u8x8_byte_stm32_hw_i2c, U8X8_MSG_BYTE_INIT). Only the clocks are
     * enabled here. */
    __HAL_RCC_GPIOB_CLK_ENABLE();
    __HAL_RCC_GPIOA_CLK_ENABLE();
}

void Error_Handler(void)
{
    __disable_irq();
    while (1) {
    }
}
